export function normalizeAnalogElectronicsKey(key) {
  if (!key) return null;
  const normalized = String(key).trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
  return ANALOG_ELECTRONICS_LESSONS[normalized] ? normalized : null;
}

export function getAnalogElectronicsLesson(key) {
  const normalized = normalizeAnalogElectronicsKey(key);
  return normalized ? ANALOG_ELECTRONICS_LESSONS[normalized] : null;
}